//! Parity between the take loop's pick and split in `voxr_narrate` and the
//! JavaScript `pick` and `breakUp` they port.
//!
//! The fixture (`tests/fixtures/narration_pick_oracle.json`) is checked in
//! and was generated by `tests/tools/narration_oracle/take_pick.mjs`, which
//! runs a patched copy of the skill's own `voxcpm` with the model call and
//! the judge stubbed: each take is graded by a scripted `(text, seed)`
//! table, and `Math.random` returns a fixed sequence. Each case here
//! replays the same script, recorded takes, cached takes and random draws
//! through [`TakeLoop::best_takes`], and compares every model and judge
//! call in order, the lines the loop prints, the parts as finally spoken,
//! the take kept for each, and the `.takes.json` written.

use std::cell::RefCell;
use std::path::Path;
use std::rc::Rc;

use serde::Deserialize;
use voxr_narrate::{
    Chunk, ChunkOptions, CloneReference, Error, Graded, PickSetup, Result, SpeakRequest,
    SpeechEngine, Take, TakeJudge, TakeLoop, TakeSpec, TakeStep, TakeStore, VoiceSource,
    chosen_takes, chunks, read_takes_file, resolve_seed,
};

mod common;
use common::{assert_oracle_current, load_json};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_pick_oracle.json"
);
const ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/take_pick.mjs"
);

#[derive(Debug, Deserialize)]
struct Fixture {
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    script: String,
    style: Option<String>,
    record: Option<String>,
    asked: Option<f64>,
    reroll: Vec<usize>,
    random: Vec<f64>,
    cached: Vec<Cached>,
    scores: Vec<Score>,
    calls: Vec<Call>,
    messages: Vec<String>,
    seed: f64,
    parts: Vec<String>,
    best: Vec<Best>,
    takes: String,
}

#[derive(Debug, Deserialize)]
struct Cached {
    text: String,
    seed: f64,
    delivery: Option<String>,
}

#[derive(Debug, Deserialize)]
struct Score {
    text: String,
    seed: f64,
    ok: bool,
    badness: Option<f64>,
}

/// One model or judge call. A judge call has no style.
#[derive(Debug, Clone, PartialEq, Deserialize)]
struct Call {
    op: String,
    text: String,
    #[serde(default)]
    style: Option<String>,
    seed: f64,
}

#[derive(Debug, Deserialize)]
struct Best {
    seed: f64,
    ok: bool,
    badness: Option<f64>,
}

type Calls = Rc<RefCell<Vec<Call>>>;

/// Records each take asked for into the shared call list.
struct Engine {
    calls: Calls,
}

impl SpeechEngine for Engine {
    type Reference = ();

    fn speak(&mut self, request: &SpeakRequest<'_, ()>) -> Result<Take> {
        assert_eq!(request.voice.kind(), "handle");
        self.calls.borrow_mut().push(Call {
            op: "speak".to_string(),
            text: request.text.to_string(),
            style: request.prefix().map(str::to_string),
            seed: request.seed,
        });
        Ok(Take {
            samples: Vec::new(),
            rate: 48000,
        })
    }
}

/// A grade from the case's score table.
struct Scored {
    ok: bool,
    badness: Option<f64>,
    why: String,
    heard: String,
}

impl Graded for Scored {
    fn ok(&self) -> bool {
        self.ok
    }

    fn badness(&self) -> Option<f64> {
        self.badness
    }

    fn why(&self) -> &str {
        &self.why
    }

    fn heard(&self) -> &str {
        &self.heard
    }
}

/// `String(x)` for the integers and halves the score tables hold.
fn js_number(x: f64) -> String {
    if x.fract() == 0.0 {
        format!("{x:.0}")
    } else {
        x.to_string()
    }
}

/// Grades by the case's `(text, seed)` table, the same as the oracle's
/// stub judge, and records each call into the shared call list.
struct Judge<'a> {
    scores: &'a [Score],
    calls: Calls,
}

impl TakeJudge for Judge<'_> {
    type Verdict = Scored;

    fn judge(&mut self, spec: &TakeSpec, _take: &Take) -> Result<Scored> {
        self.calls.borrow_mut().push(Call {
            op: "judge".to_string(),
            text: spec.text.clone(),
            style: None,
            seed: spec.seed,
        });
        let hit = self
            .scores
            .iter()
            .find(|s| s.text == spec.text && s.seed == spec.seed);
        let (ok, badness) = hit.map_or((true, Some(0.0)), |s| (s.ok, s.badness));
        Ok(Scored {
            ok,
            badness,
            why: format!("bad {}", badness.map_or("none".to_string(), js_number)),
            heard: format!("heard {}", spec.text),
        })
    }
}

/// Holds takes by `(text, seed, delivery)`.
struct Store {
    held: Vec<(String, f64, Option<String>)>,
}

impl Store {
    fn key(spec: &TakeSpec) -> (String, f64, Option<String>) {
        (spec.text.clone(), spec.seed, spec.delivery.clone())
    }
}

impl TakeStore for Store {
    fn has(&mut self, spec: &TakeSpec) -> bool {
        self.held.contains(&Self::key(spec))
    }

    fn load(&mut self, spec: &TakeSpec) -> Result<Take> {
        if !self.has(spec) {
            return Err(Error::DataError {
                reason: format!("no take of {:?} at seed {}", spec.text, spec.seed),
            });
        }
        Ok(Take {
            samples: Vec::new(),
            rate: 48000,
        })
    }

    fn save(&mut self, spec: &TakeSpec, _take: &Take) -> Result<()> {
        self.held.push(Self::key(spec));
        Ok(())
    }
}

fn run(case: &Case) -> Result<()> {
    let name = &case.name;
    let units: Vec<Chunk> = chunks(
        &case.script,
        ChunkOptions {
            lines: false,
            max: 700,
            whole: true,
        },
    )?;
    let read = read_takes_file(case.record.as_deref().unwrap_or(""));
    let resolved = resolve_seed(case.asked, &read, None);
    assert_eq!(resolved.seed, case.seed, "run seed, case {name}");
    let chosen = chosen_takes(read, &resolved);

    let calls: Calls = Rc::default();
    let mut engine = Engine {
        calls: Rc::clone(&calls),
    };
    let mut judge = Judge {
        scores: &case.scores,
        calls: Rc::clone(&calls),
    };
    let mut store = Store {
        held: case
            .cached
            .iter()
            .map(|c| (c.text.clone(), c.seed, c.delivery.clone()))
            .collect(),
    };
    let mut draws = case.random.iter().copied();
    let mut random = || {
        draws
            .next()
            .unwrap_or_else(|| panic!("case {name} drew more than its random values"))
    };
    let mut take_loop = TakeLoop {
        setup: PickSetup {
            seed: resolved.seed,
            chosen: &chosen,
            style: case.style.as_deref(),
            voice: VoiceSource::Clone {
                reference: CloneReference::Handle(&()),
                transcript: None,
            },
            cfg: 1.6,
            steps: 16,
        },
        engine: &mut engine,
        judge: &mut judge,
        store: &mut store,
    };
    let mut live: Vec<TakeStep> = Vec::new();
    let got = take_loop.best_takes(units, &case.reroll, &mut random, &mut live)?;

    assert_eq!(*calls.borrow(), case.calls, "calls, case {name}");
    // The steps as they happened, and the copy the result keeps.
    let messages: Vec<String> = live.iter().filter_map(|s| s.message()).collect();
    assert_eq!(messages, case.messages, "messages, case {name}");
    assert_eq!(live, got.log, "kept steps, case {name}");
    let parts: Vec<&str> = got.parts.iter().map(|p| p.text.as_str()).collect();
    assert_eq!(parts, case.parts, "parts, case {name}");
    assert_eq!(got.best.len(), case.best.len(), "best count, case {name}");
    for (i, (b, want)) in got.best.iter().zip(&case.best).enumerate() {
        assert_eq!(b.seed, want.seed, "best[{i}] seed, case {name}");
        assert_eq!(b.verdict.ok, want.ok, "best[{i}] ok, case {name}");
        assert_eq!(
            b.verdict.badness, want.badness,
            "best[{i}] badness, case {name}"
        );
    }
    assert_eq!(
        got.takes_file(resolved.seed).write()?,
        case.takes,
        "takes.json, case {name}"
    );
    Ok(())
}

#[test]
fn matches_javascript_on_every_case() -> Result<()> {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");
    for case in &fixture.cases {
        run(case)?;
    }
    Ok(())
}

#[test]
fn oracle_fixture_is_current() {
    assert_oracle_current(ORACLE, FIXTURE);
}
